def fill_granted_on(apps: Apps, schema_editor: BaseDatabaseSchemaEditor | None) -> None:
    """Give Visas granted before this day the day their Student moved to Completed.

    Without such a History entry (e.g. the Student was already Completed), the Visa's start day.
    Only Granted Visas are read, so this stays light.
    """
    visa_model = apps.get_model("applications", "Visa")
    history_model = apps.get_model("history", "HistoryEntry")
    for visa in visa_model.objects.filter(status="granted", granted_on__isnull=True).iterator():
        moment = (
            history_model.objects.filter(
                student_id=visa.student_id, kind="stage_changed", after="completed"
            )
            .order_by("-at")
            .values_list("at", flat=True)
            .first()
        )
        visa.granted_on = timezone.localdate(moment) if moment else visa.started_on
        visa.save(update_fields=["granted_on"])


